    /** 查表；未知名称退回 layers，与本体行为一致。 */
    fun pathFor(name: String?): String {
        val key = name?.trim()?.lowercase().orEmpty()
        return table[key] ?: table[FALLBACK]!!
    }

    /** 是否是需要画矢量图的图标名（用于 UI 判断） */
    fun has(name: String?): Boolean =
        table.containsKey(name?.trim()?.lowercase().orEmpty())

    /** 全部可选图标名，对应本体 EXPERT_ICON_NAMES */
    val names: List<String> get() = table.keys.toList()
